[{"order":1,"type":"heading","text":"Introduction to Observability in Go"},{"order":2,"type":"paragraph","text":"Observability in modern Go applications allows developers to understand the internal state of a system by examining its external outputs. The three pillars of observability are metrics, logs, and traces. In this tutorial, we will explore how to implement metrics and tracing in a Go HTTP service using OpenTelemetry and Prometheus."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"paragraph","text":"Before starting, ensure you have Go 1.19 or higher installed. Initialize a new Go module and install the necessary OpenTelemetry and Prometheus packages using the following commands."},{"order":5,"type":"code","text":"go mod init go-observability-demo
go get go.opentelemetry.io/otel
go get github.com/prometheus/client_golang/prometheus
go get github.com/prometheus/client_golang/prometheus/promhttp"},{"order":6,"type":"heading","text":"Implementing Metrics with Prometheus"},{"order":7,"type":"paragraph","text":"Metrics provide numerical data about your application performance, such as request counts, error rates, and memory usage. Prometheus is the industry standard for scraping and querying time-series metrics."},{"order":8,"type":"code","text":"package main

import (
	"net/http"
	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promhttp"
)

var (
	httpRequestsTotal = prometheus.NewCounterVec(
		prometheus.CounterOpts{
			Name: "http_requests_total",
			Help: "Total number of HTTP requests.",
		},
		[]string{"method", "endpoint"},
	)
)

func init() {
	prometheus.MustRegister(httpRequestsTotal)
}"},{"order":9,"type":"subheading","text":"Exposing the Metrics Endpoint"},{"order":10,"type":"paragraph","text":"To allow Prometheus to scrape your metrics, you need to expose an HTTP handler that returns the registered metrics in a text format."},{"order":11,"type":"code","text":"func metricsMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		httpRequestsTotal.WithLabelValues(r.Method, r.URL.Path).Inc()
		next.ServeHTTP(w, r)
	})
}"},{"order":12,"type":"heading","text":"Implementing Distributed Tracing"},{"order":13,"type":"paragraph","text":"Distributed tracing tracks the journey of a single request as it propagates across multiple microservices. OpenTelemetry (OTel) provides a vendor-neutral API for generating spans and traces."},{"order":14,"type":"code","text":"package main

import (
	"context"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/trace"
)

var tracer = otel.Tracer("go-observability-demo")

func processOrder(ctx context.Context) error {
	_, span := tracer.Start(ctx, "processOrder")
	defer span.End()

	// Simulate business logic
	return nil
}"},{"order":15,"type":"subheading","text":"Putting It All Together"},{"order":16,"type":"paragraph","text":"Combine your metrics middleware and tracing into a cohesive main function to run the HTTP server."},{"order":17,"type":"code","text":"func main() {
	mux := http.NewServeMux()
	mux.Handle("/metrics", promhttp.Handler())

	mux.HandleFunc("/order", func(w http.ResponseWriter, r *http.Request) {
		ctx, span := tracer.Start(r.Context(), "HTTP /order")
		defer span.End()

		_ = processOrder(ctx)
		w.WriteHeader(http.StatusOK)
		w.Write([]byte("Order processed successfully"))
	})

	wrappedMux := metricsMiddleware(mux)
	http.ListenAndServe(":8080", wrappedMux)
}"},{"order":18,"type":"heading","text":"Best Practices for Go Observability"},{"order":19,"type":"bullet_point","text":"Always pass context.Context as the first argument in functions to ensure trace propagation works seamlessly."},{"order":20,"type":"bullet_point","text":"Use structured logging alongside traces and metrics to correlate log events with specific request IDs or trace IDs."},{"order":21,"type":"bullet_point","text":"Avoid high cardinality labels in Prometheus metrics, such as storing raw user IDs or full error messages, to prevent memory bloat."}]
